// $ cua-driver call launch_app '{"bundle_id": "com.apple.calculator"}'
{
  "bundle_id": "com.apple.calculator",
  "name": "Calculator",
  "pid": 84780,
  "windows": [
    {
      "app_name": "计算器",
      "title": "计算器",
      "window_id": 102295
    }
  ]
}

// 2. Filtering list_windows by "Calculator" returns empty:
// $ cua-driver call list_windows '{"app": "Calculator"}'
{
  "windows": []
}

// 3. Filtering by localized name "计算器" or bundle_id "com.apple.calculator" works:
// $ cua-driver call list_windows '{"app": "com.apple.calculator"}'
{
  "windows": [
    {
      "app_name": "计算器",
      "pid": 84780,
      "title": "计算器",
      "window_id": 102295
