   const driver = CuaDriver.createPrivateWorker({
     binaryPath: "C:\\path\\to\\cua-driver.exe",
     hostBundleId: "com.example.repro",
     configuredDriver: {
       claudeCodeCompatibility: false,
       authorization: {
